import { LIFECYCLE_CONDITIONAL_CAMPAIGN_KEY, LIFECYCLE_COOLDOWN_HOURS, LIFECYCLE_PRIORITY, type LifecycleRuntimeConfig } from "./lifecycleConstants.js";
import { chooseHighestPriority, evaluateKnownRule, getNextBestAction, shouldSkipSequenceStep } from "./lifecycleRules.js";
import { ensureLifecycleEnrollment, getLifecyclePreferences, getLifecycleRuntimeConfig, findCampaign, recordLifecycleEvent } from "./lifecycleRepository.js";
import { getOrRecalculateLifecycleState } from "./lifecycleStateService.js";
import { calculateNextSequenceStepAt } from "./lifecycleSequenceTiming.js";
import type { LifecycleCandidate, LifecycleDependencies, LifecycleOperationalContext, LifecycleRule, LifecycleState, LifecycleStep } from "./lifecycleTypes.js";

type LifecycleSchedulerBatchResult = {
  scheduled: number;
  failed: number;
};

export async function processLifecycleSchedulerUsers<T extends { id: string; created_at?: string }>(
  users: T[],
  processUser: (user: T) => Promise<unknown>,
  onError: (user: T, error: unknown) => void = (user, error) => {
    console.error(`[Lifecycle Scheduler] Falha para ${user.id}:`, error instanceof Error ? error.message : error);
  }
): Promise<LifecycleSchedulerBatchResult> {
  let scheduled = 0;
  let failed = 0;

  for (const user of users) {
    try {
      if (await processUser(user) === "scheduled") scheduled += 1;
    } catch (error) {
      failed += 1;
      onError(user, error);
    }
  }

  return { scheduled, failed };
}

export function assertLifecycleSchedulerHealthy(result: LifecycleSchedulerBatchResult, users: number): void {
  if (result.failed === 0) return;
  throw new Error(`Lifecycle scheduler falhou para ${result.failed} de ${users} usuário(s); ${result.scheduled} mensagem(ns) foram agendadas antes da falha.`);
}

function firstName(value: string) { return value.trim().split(/\s+/)[0] || "Profissional"; }

function zonedDateParts(value: Date, timeZone: string) {
  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
  });
  return Object.fromEntries(formatter.formatToParts(value).filter((part) => part.type !== "literal").map((part) => [part.type, part.value])) as Record<string, string>;
}

function localDateTimeToUtc(year: number, month: number, day: number, hour: number, minute: number, timeZone: string): Date {
  const localAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
  const offsetParts = zonedDateParts(new Date(localAsUtc), timeZone);
  const renderedAsUtc = Date.UTC(Number(offsetParts.year), Number(offsetParts.month) - 1, Number(offsetParts.day), Number(offsetParts.hour), Number(offsetParts.minute), Number(offsetParts.second));
  return new Date(localAsUtc - (renderedAsUtc - localAsUtc));
}

function nextPreferredSendAt(reference: Date, timeZone: string, preferredTime: string | null | undefined, minimumDelayMinutes: number): Date {
  const safeTime = /^([01]\d|2[0-3]):[0-5]\d/.test(String(preferredTime || "")) ? String(preferredTime) : "08:30";
  const [hour, minute] = safeTime.split(":").map(Number);
  const notBefore = new Date(reference.getTime() + Math.max(0, minimumDelayMinutes) * 60000);
  const current = zonedDateParts(notBefore, timeZone);
  let target = localDateTimeToUtc(Number(current.year), Number(current.month), Number(current.day), hour, minute, timeZone);
  if (target.getTime() < notBefore.getTime()) {
    const nextLocalDay = new Date(Date.UTC(Number(current.year), Number(current.month) - 1, Number(current.day) + 1));
    target = localDateTimeToUtc(nextLocalDay.getUTCFullYear(), nextLocalDay.getUTCMonth() + 1, nextLocalDay.getUTCDate(), hour, minute, timeZone);
  }
  return target;
}

function safeTimeZone(value: unknown, fallback = "America/Sao_Paulo"): string {
  try {
    const candidate = String(value || fallback);
    new Intl.DateTimeFormat("en-US", { timeZone: candidate }).format();
    return candidate;
  } catch {
    return fallback;
  }
}

function buildTemplateContext(state: LifecycleState, origin: string, now: Date): Record<string, string | number> {
  const nextAction = getNextBestAction(state);
  const daysRemaining = state.trialEndsAt ? Math.ceil((new Date(state.trialEndsAt).getTime() - now.getTime()) / 86400000) : 0;
  return {
    primeiro_nome: firstName(state.fullName),
    nome_completo: state.fullName,
    profissao: state.profession || "profissional",
    quantidade_pacientes: state.patientsCount,
    quantidade_prontuarios: state.linkedRecordsCount,
    quantidade_evolucoes: state.evolutionsCount,
    resumo_progresso: "",
    quantidade_audios: state.audioEvolutionsCount,
    quantidade_documentos: state.reportsCount,
    quantidade_recursos: state.resourcesCount,
    plano_atual: state.subscriptionPlan || "seu plano atual",
    data_fim_teste: state.trialEndsAt ? new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Sao_Paulo", day: "2-digit", month: "2-digit", year: "numeric" }).format(new Date(state.trialEndsAt)) : "",
    dias_restantes_teste: Math.max(daysRemaining, 0),
    proxima_acao: nextAction.label,
    texto_cta_proxima_acao: nextAction.ctaLabel,
    link_acao: nextAction.route,
    url_proxima_acao: nextAction.route,
    link_suporte: `${origin.replace(/\/$/, "")}/painel/support`
  };
}

function sequenceCandidate(step: LifecycleStep, campaignKey: string, periodKey: string): LifecycleCandidate {
  return {
    messageKey: `sequence:${step.step_key}`,
    priority: Number(step.priority || LIFECYCLE_PRIORITY.sequence),
    dispatchType: "sequence",
    category: step.category || "education",
    commercial: step.category === "commercial",
    step,
    subjectTemplate: step.subject_template,
    preheaderTemplate: step.preheader_template || "Continue de onde parou.",
    bodyTemplate: step.body_markdown,
    ctaLabelTemplate: step.cta_label_template || "Acessar a plataforma",
    ctaRouteTemplate: step.cta_route_template || step.fallback_cta_route || "/painel/dashboard",
    dedupePeriodKey: `${campaignKey}:${periodKey}`,
    reason: `passo ${step.position} devido`
  };
}

function applyConditionalStepTemplate(candidate: LifecycleCandidate, step: LifecycleStep): LifecycleCandidate {
  return {
    ...candidate,
    step,
    category: step.category || candidate.category,
    commercial: step.category === "commercial" || candidate.commercial,
    subjectTemplate: step.subject_template,
    preheaderTemplate: step.preheader_template || candidate.preheaderTemplate,
    bodyTemplate: step.body_markdown,
    ctaLabelTemplate: step.cta_label_template || candidate.ctaLabelTemplate,
    ctaRouteTemplate: step.cta_route_template || step.fallback_cta_route || candidate.ctaRouteTemplate
  };
}

async function ensureConditionalRecoveryEnrollment(deps: LifecycleDependencies, userId: string, campaign: any, now: Date) {
  const { data: existing, error: lookupError } = await deps.supabaseAdmin
    .from("lifecycle_enrollments")
    .select("*")
    .eq("user_id", userId)
    .eq("campaign_id", campaign.id)
    .maybeSingle();
  if (lookupError) throw new Error(lookupError.message || "Falha ao consultar matrícula condicional.");
  if (existing?.status === "active") return existing;

  const enrollment = {
    status: "active",
    enrolled_at: now.toISOString(),
    started_at: now.toISOString(),
    current_position: 0,
    next_step_at: now.toISOString(),
    completion_deadline_at: new Date(now.getTime() + Number(campaign.completion_window_days || 25) * 86400000).toISOString(),
    completed_at: null,
    paused_at: null,
    cancelled_at: null,
    pause_reason: null,
    cancellation_reason: null,
    updated_at: now.toISOString()
  };

  if (existing) {
    const { data, error } = await deps.supabaseAdmin.from("lifecycle_enrollments").update(enrollment).eq("id", existing.id).select("*").single();
    if (error) throw new Error(error.message || "Falha ao reativar matrícula condicional.");
    return data;
  }

  const { data, error } = await deps.supabaseAdmin.from("lifecycle_enrollments").insert({
    ...enrollment,
    user_id: userId,
    campaign_id: campaign.id
  }).select("*").single();
  if (error) throw new Error(error.message || "Falha ao criar matrícula condicional.");
  return data;
}

function isRelationshipCooldownBlocked(state: LifecycleState, now: Date, candidate: LifecycleCandidate): boolean {
  if (candidate.dispatchType === "transactional_bridge") return false;
  if (candidate.dispatchType === "sequence") return false;
  return Boolean(state.nextRelationshipEmailEligibleAt && new Date(state.nextRelationshipEmailEligibleAt).getTime() > now.getTime());
}

function isOperationalCandidate(candidate: LifecycleCandidate): boolean {
  return candidate.category === "operational" || candidate.category === "billing" || candidate.category === "technical";
}

function processingEligibilityMinutes(rule: LifecycleRule): number {
  const technicalThreshold = Number(rule.condition_config?.processing_threshold_minutes || 120);
  return technicalThreshold + Math.max(0, Number(rule.delay_minutes || 0));
}

async function getCandidateLimitReason(deps: LifecycleDependencies, userId: string, candidate: LifecycleCandidate, now: Date): Promise<string | null> {
  const activeStatuses = ["queued", "processing", "retry", "sent"];
  const { data, error } = await deps.supabaseAdmin
    .from("lifecycle_dispatches")
    .select("message_key, dispatch_type, metadata, priority, status, created_at, sent_at, scheduled_for")
    .eq("user_id", userId)
    .in("status", activeStatuses)
    .order("created_at", { ascending: false })
    .limit(100);
  if (error) throw new Error(error.message || "Falha ao verificar limites de frequência lifecycle.");

  const dispatches = (data || []) as Array<Record<string, unknown>>;
  const operationalPending = dispatches.some((item) =>
    ["queued", "processing", "retry"].includes(String(item.status)) &&
    ["operational", "billing", "technical"].includes(String((item.metadata as any)?.category || ""))
  );
  if (!isOperationalCandidate(candidate) && operationalPending) return "operational_dispatch_pending";

  const higherPriorityPending = dispatches.some((item) =>
    ["queued", "processing", "retry"].includes(String(item.status)) &&
    Number(item.priority || 0) > candidate.priority
  );
  if (higherPriorityPending) return "higher_priority_dispatch_pending";

  if (isOperationalCandidate(candidate)) return null;

  const nowMs = now.getTime();
  const recent = dispatches.filter((item) => {
    const timestamp = new Date(String(item.sent_at || item.created_at || item.scheduled_for || "")).getTime();
    return Number.isFinite(timestamp) && nowMs - timestamp >= 0;
  });
  const conditionalRecent = recent.filter((item) => item.dispatch_type === "conditional" && !["operational", "billing", "technical"].includes(String((item.metadata as any)?.category || "")));
  const last24h = conditionalRecent.filter((item) => nowMs - new Date(String(item.sent_at || item.created_at || item.scheduled_for)).getTime() <= 24 * 60 * 60 * 1000);
  const last7d = conditionalRecent.filter((item) => nowMs - new Date(String(item.sent_at || item.created_at || item.scheduled_for)).getTime() <= 7 * 24 * 60 * 60 * 1000);
  if (last24h.length >= 1) return "conditional_frequency_24h_limit";
  if (last7d.length >= 2) return "conditional_frequency_7d_limit";
  return null;
}

async function insertDecision(deps: LifecycleDependencies, row: Record<string, unknown>) {
  const { error } = await deps.supabaseAdmin.from("lifecycle_decisions").upsert(row, { onConflict: "decision_key", ignoreDuplicates: true });
  if (error && error.code !== "23505") throw new Error(error.message || "Falha ao registrar decisão lifecycle.");
}

async function insertSkippedDispatch(deps: LifecycleDependencies, row: Record<string, unknown>) {
  const { error } = await deps.supabaseAdmin.from("lifecycle_dispatches").insert(row);
  if (error && error.code !== "23505") throw new Error(error.message || "Falha ao registrar skip lifecycle.");
}

function sequenceDue(step: LifecycleStep | undefined, enrollment: any, now: Date): boolean {
  if (!step || enrollment.current_position >= step.position) return false;
  const startedAt = new Date(enrollment.started_at || enrollment.enrolled_at).getTime();
  const dueAt = startedAt + Number(step.wait_minutes || 0) * 60000;
  return now.getTime() >= dueAt && (!enrollment.next_step_at || now.getTime() >= new Date(enrollment.next_step_at).getTime());
}

async function findLongPendingEvolution(deps: LifecycleDependencies, userId: string, minimumAgeMinutes: number, now: Date) {
  const { data, error } = await deps.supabaseAdmin
    .from("evolutions")
    .select("id, transcription_status, google_doc_append_status, created_at, updated_at")
    .eq("professional_id", userId)
    .or("transcription_status.eq.processing,google_doc_append_status.eq.pending")
    .order("created_at", { ascending: true });
  if (error) throw new Error(error.message || "Falha ao consultar evoluções pendentes.");
  const threshold = now.getTime() - Math.max(0, minimumAgeMinutes) * 60000;
  return (data || []).find((evolution: any) => {
    const isPending = evolution.transcription_status === "processing" || evolution.google_doc_append_status === "pending";
    const referenceTime = new Date(evolution.updated_at || evolution.created_at || 0).getTime();
    return isPending && Number.isFinite(referenceTime) && referenceTime <= threshold;
  }) || null;
}

async function loadOperationalContext(deps: LifecycleDependencies, userId: string): Promise<LifecycleOperationalContext> {
  const [failedEvolution, notAddedEvolution, professional, failedPayment] = await Promise.all([
    deps.supabaseAdmin.from("evolutions").select("id, updated_at").eq("professional_id", userId).eq("transcription_status", "failed").order("updated_at", { ascending: false }).limit(1).maybeSingle(),
    deps.supabaseAdmin.from("evolutions").select("id, updated_at").eq("professional_id", userId).eq("transcription_status", "completed").eq("google_doc_append_status", "failed").order("updated_at", { ascending: false }).limit(1).maybeSingle(),
    deps.supabaseAdmin.from("professionals").select("force_google_disconnect, updated_at").eq("id", userId).maybeSingle(),
    deps.supabaseAdmin.from("transactions").select("id, created_at").eq("professional_id", userId).eq("status", "failed").order("created_at", { ascending: false }).limit(1).maybeSingle()
  ]);
  const error = failedEvolution.error || notAddedEvolution.error || professional.error || failedPayment.error;
  if (error) throw new Error(error.message || "Falha ao carregar sinais operacionais do lifecycle.");
  return {
    failedEvolution: failedEvolution.data ? { id: failedEvolution.data.id, updatedAt: failedEvolution.data.updated_at || null } : null,
    notAddedEvolution: notAddedEvolution.data ? { id: notAddedEvolution.data.id, updatedAt: notAddedEvolution.data.updated_at || null } : null,
    googleConnection: professional.data?.force_google_disconnect ? { updatedAt: professional.data.updated_at || null } : null,
    failedPayment: failedPayment.data ? { id: failedPayment.data.id, updatedAt: failedPayment.data.created_at || null } : null
  };
}

async function scheduleForEnrollment(
  deps: LifecycleDependencies,
  campaign: any,
  enrollment: any,
  steps: LifecycleStep[],
  conditionalCampaign: any | null,
  conditionalSteps: LifecycleStep[],
  rules: LifecycleRule[],
  state: LifecycleState,
  operational: LifecycleOperationalContext,
  runtime: LifecycleRuntimeConfig,
  now: Date
) {
  if (enrollment.status !== "active") return "inactive";
  if (enrollment.completion_deadline_at && new Date(enrollment.completion_deadline_at).getTime() < now.getTime()) {
    await deps.supabaseAdmin.from("lifecycle_enrollments").update({ status: "expired", cancellation_reason: "completion_window_expired" }).eq("id", enrollment.id);
    await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: campaign.id, decision_key: `deadline:${enrollment.id}`, outcome: "completed", reason: "janela máxima da jornada excedida" });
    return "expired";
  }

  const preferences = await getLifecyclePreferences(deps, state.userId);
  if (!preferences.lifecycle_enabled || !preferences.product_education_enabled) {
    await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: campaign.id, decision_key: `suppressed:${enrollment.id}:${now.toISOString().slice(0, 10)}`, outcome: "suppressed", reason: "preferência de comunicação desativada" });
    return "suppressed";
  }

  const currentStep = steps.find((step) => step.position === enrollment.current_position + 1);
  const candidates = rules.map((rule) => {
    const candidate = evaluateKnownRule(rule, state, now, operational);
    if (!candidate || conditionalCampaign?.status !== "active") return null;
    const templateStep = conditionalSteps.find((step) => step.eligibility_rule_key === rule.rule_key && step.status === "active" && step.enabled);
    return templateStep ? applyConditionalStepTemplate(candidate, templateStep) : null;
  }).filter(Boolean) as LifecycleCandidate[];
  let sequence = sequenceDue(currentStep, enrollment, now) && currentStep ? sequenceCandidate(currentStep, campaign.key, now.toISOString().slice(0, 10)) : null;
  if (sequence && shouldSkipSequenceStep(currentStep!, state)) {
    const skipReason = shouldSkipSequenceStep(currentStep!, state) || "passo obsoleto";
    const decisionKey = `skip:${enrollment.id}:${currentStep!.id}`;
    await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: campaign.id, step_id: currentStep!.id, decision_key: decisionKey, selected_message_key: sequence.messageKey, selected_priority: sequence.priority, outcome: runtime.dry_run || !runtime.send_enabled ? "dry_run" : "skipped", reason: skipReason });
    if (!runtime.dry_run && runtime.send_enabled) {
      await insertSkippedDispatch(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: campaign.id, step_id: currentStep!.id, message_key: sequence.messageKey, dispatch_type: "sequence", priority: sequence.priority, status: "skipped", scheduled_for: now.toISOString(), dedupe_key: `sequence:${enrollment.id}:${currentStep!.id}`, skip_reason: skipReason, skipped_at: now.toISOString() });
      const nextStep = steps.find((s) => s.position === currentStep!.position + 1);
      const nextStepAt = nextStep
        ? calculateNextSequenceStepAt(now, currentStep!.wait_minutes, nextStep.wait_minutes).toISOString()
        : null;
      await deps.supabaseAdmin.from("lifecycle_enrollments").update({ current_position: currentStep!.position, next_step_at: nextStepAt }).eq("id", enrollment.id);
    }
    sequence = null;
  }

  const allCandidates = [...candidates, ...(sequence ? [sequence] : [])];
  if (allCandidates.length === 0) return "nothing_due";

  const candidateDedupeKeys = allCandidates.map(c => `${c.dispatchType}:${state.userId}:${c.messageKey}:${c.resourceId && c.occurrenceId ? `${c.resourceId}:${c.occurrenceId}` : c.dedupePeriodKey}`);

  const { data: existingDispatches, error: dedupeError } = await deps.supabaseAdmin
    .from("lifecycle_dispatches")
    .select("dedupe_key")
    .in("dedupe_key", candidateDedupeKeys);

  if (dedupeError) throw new Error(dedupeError.message);

  const existingDedupeSet = new Set((existingDispatches || []).map((d: any) => d.dedupe_key));
  const eligibleCandidates = allCandidates.filter(c => {
    const key = `${c.dispatchType}:${state.userId}:${c.messageKey}:${c.resourceId && c.occurrenceId ? `${c.resourceId}:${c.occurrenceId}` : c.dedupePeriodKey}`;
    return !existingDedupeSet.has(key);
  });

  const chosen = chooseHighestPriority(eligibleCandidates);
  if (!chosen) return "nothing_due";

  let processingEvolutionId: string | null = null;
  let processingDedupeKey = chosen.resourceId && chosen.occurrenceId ? `${chosen.resourceId}:${chosen.occurrenceId}` : chosen.dedupePeriodKey;
  if (chosen.rule?.rule_key === "evolution_processing_too_long") {
    const pendingEvolution = await findLongPendingEvolution(deps, state.userId, processingEligibilityMinutes(chosen.rule), now);
    if (!pendingEvolution) return "nothing_due";
    processingEvolutionId = pendingEvolution.id;
    processingDedupeKey = `processing:${pendingEvolution.id}`;

    const { data: previousAlerts, error: previousAlertsError } = await deps.supabaseAdmin
      .from("lifecycle_dispatches")
      .select("metadata, status")
      .eq("user_id", state.userId)
      .eq("rule_id", chosen.rule.id)
      .in("status", ["queued", "processing", "retry", "sent", "failed"]);
    if (previousAlertsError) throw new Error(previousAlertsError.message || "Falha ao verificar alertas de processamento anteriores.");
    if ((previousAlerts || []).some((item: any) => item.metadata?.processing_evolution_id === processingEvolutionId)) return "nothing_due";
  }
  if (isRelationshipCooldownBlocked(state, now, chosen)) {
    await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: chosen.step?.campaign_id || campaign.id, step_id: chosen.step?.id || null, rule_id: chosen.rule?.id || null, decision_key: `deferred:${enrollment.id}:${chosen.messageKey}:${now.toISOString().slice(0, 10)}`, selected_message_key: chosen.messageKey, selected_priority: chosen.priority, outcome: "deferred", reason: "cooldown de 24 horas" });
    await deps.supabaseAdmin.from("lifecycle_enrollments").update({ next_step_at: state.nextRelationshipEmailEligibleAt }).eq("id", enrollment.id);
    return "deferred";
  }

  const limitReason = await getCandidateLimitReason(deps, state.userId, chosen, now);
  if (limitReason) {
    await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: chosen.step?.campaign_id || campaign.id, step_id: chosen.step?.id || null, rule_id: chosen.rule?.id || null, decision_key: `deferred:${enrollment.id}:${chosen.messageKey}:${now.toISOString().slice(0, 10)}:${limitReason}`, selected_message_key: chosen.messageKey, selected_priority: chosen.priority, outcome: "deferred", reason: limitReason });
    await deps.supabaseAdmin.from("lifecycle_enrollments").update({ next_step_at: new Date(now.getTime() + 60 * 60000).toISOString() }).eq("id", enrollment.id);
    return "deferred";
  }

  const context = buildTemplateContext(state, deps.productionOrigin, now);
  const chosenCampaignId = chosen.step?.campaign_id || campaign.id;
  const decisionKey = `${chosen.dispatchType}:${enrollment.id}:${chosen.messageKey}:${processingDedupeKey}`;
  const dryRun = runtime.dry_run || !runtime.send_enabled;
  await insertDecision(deps, { user_id: state.userId, enrollment_id: enrollment.id, campaign_id: chosenCampaignId, step_id: chosen.step?.id || null, rule_id: chosen.rule?.id || null, decision_key: decisionKey, selected_message_key: chosen.messageKey, selected_priority: chosen.priority, outcome: dryRun ? "dry_run" : "scheduled", reason: chosen.reason, metadata: { cta_route: chosen.ctaRouteTemplate, category: chosen.category, context_keys: Object.keys(context) } });
  if (dryRun) return "dry_run";

  const delayMinutes = chosen.rule?.rule_key === "evolution_processing_too_long" ? 0 : Number(chosen.rule?.delay_minutes || 0);
  const scheduledFor = nextPreferredSendAt(
    now,
    safeTimeZone(preferences.timezone || campaign.timezone),
    preferences.preferred_send_time || chosen.step?.send_time || campaign.default_send_time,
    delayMinutes
  );
  const { error: dispatchError } = await deps.supabaseAdmin.from("lifecycle_dispatches").insert({
    user_id: state.userId,
    enrollment_id: enrollment.id,
    campaign_id: chosenCampaignId,
    step_id: chosen.step?.id || null,
    rule_id: chosen.rule?.id || null,
    message_key: chosen.messageKey,
    dispatch_type: chosen.dispatchType,
    priority: chosen.priority,
    status: "queued",
    scheduled_for: scheduledFor.toISOString(),
    dedupe_key: `${chosen.dispatchType}:${state.userId}:${chosen.messageKey}:${processingDedupeKey}`,
    metadata: { ...context, ...(processingEvolutionId ? { processing_evolution_id: processingEvolutionId } : {}), ...(chosen.resourceId ? { resource_id: chosen.resourceId } : {}), ...(chosen.occurrenceId ? { occurrence_id: chosen.occurrenceId } : {}), ...(chosen.rule?.condition_config?.email_only === true ? { force_email_only: true } : {}), cta_label_template: chosen.ctaLabelTemplate, cta_route_template: chosen.ctaRouteTemplate, category: chosen.category, commercial: chosen.commercial }
  });
  if (dispatchError && dispatchError.code !== "23505") throw new Error(dispatchError.message || "Falha ao criar dispatch lifecycle.");

  const nextStepAt = chosen.dispatchType === "sequence"
    ? scheduledFor.toISOString()
    : currentStep
      ? new Date(now.getTime() + 86400000).toISOString()
      : null;
  await deps.supabaseAdmin.from("lifecycle_enrollments").update({
    next_step_at: nextStepAt
  }).eq("id", enrollment.id);
  return "scheduled";
}

export async function scheduleLifecycleMessages(deps: LifecycleDependencies, now = new Date()) {
  const runtime = await getLifecycleRuntimeConfig(deps);
  const activationCampaign = await findCampaign(deps, "new_user_activation_15d");
  const conditionalCampaign = await findCampaign(deps, LIFECYCLE_CONDITIONAL_CAMPAIGN_KEY);
  const campaign = activationCampaign?.status === "active" ? activationCampaign : null;
  if (!campaign) return { scheduled: 0, dryRun: runtime.dry_run || !runtime.send_enabled, reason: "campaign_not_active" };
  const [{ data: steps, error: stepsError }, { data: rules, error: rulesError }, { data: professionals, error: professionalsError }, { data: conditionalSteps, error: conditionalStepsError }] = await Promise.all([
    activationCampaign?.status === "active"
      ? deps.supabaseAdmin.from("lifecycle_steps").select("*").eq("campaign_id", activationCampaign.id).eq("enabled", true).order("position")
      : Promise.resolve({ data: [] as any[], error: null }),
    deps.supabaseAdmin.from("lifecycle_rules").select("*").eq("enabled", true),
    deps.supabaseAdmin.from("professionals").select("id, status, role, created_at").eq("status", "active").neq("role", "admin").limit(500),
    conditionalCampaign
      ? deps.supabaseAdmin.from("lifecycle_steps").select("*").eq("campaign_id", conditionalCampaign.id).eq("enabled", true).order("position")
      : Promise.resolve({ data: [] as any[], error: null })
  ]);
  if (stepsError || rulesError || professionalsError || conditionalStepsError) throw new Error(stepsError?.message || rulesError?.message || professionalsError?.message || conditionalStepsError?.message || "Falha ao buscar dados do scheduler lifecycle.");
  const users = professionals || [];
  const batchResult = await processLifecycleSchedulerUsers(users, async (professional) => {
    const state = await getOrRecalculateLifecycleState(deps, professional.id);
    const operational = await loadOperationalContext(deps, professional.id);
    const enrollment = await ensureLifecycleEnrollment(deps, professional.id, { campaignKey: campaign.key });
    let result: unknown;

    if (enrollment?.status === "active") {
      result = await scheduleForEnrollment(deps, campaign, enrollment, steps || [], conditionalCampaign, conditionalSteps || [], rules || [], state, operational, runtime, now);
    } else {
      const recoveryRule = (rules || []).find((rule) => rule.rule_key === "trial_canceled_reengagement_3d");
      const recoveryStep = (conditionalSteps || []).find((step) => step.eligibility_rule_key === recoveryRule?.rule_key && step.status === "active" && step.enabled);
      const recoveryCandidate = recoveryRule ? evaluateKnownRule(recoveryRule, state, now, operational) : null;
      if (!conditionalCampaign || conditionalCampaign.status !== "active" || !recoveryStep || !recoveryCandidate) {
        return enrollment ? "inactive" : "not_enrolled";
      }
      const conditionalEnrollment = await ensureConditionalRecoveryEnrollment(deps, professional.id, conditionalCampaign, now);
      result = await scheduleForEnrollment(deps, conditionalCampaign, conditionalEnrollment, [], conditionalCampaign, conditionalSteps || [], rules || [], state, operational, runtime, now);
    }
    if (state.subscriptionStatus === "trialing" && state.trialEndsAt) {
      const trialDays = Math.ceil((new Date(state.trialEndsAt).getTime() - now.getTime()) / 86400000);
      if (trialDays > 0 && trialDays <= 3) await recordLifecycleEvent(deps, { userId: professional.id, eventName: "trial_expiring", source: "backend", metadata: { days: trialDays }, idempotencyKey: `trial_expiring:${professional.id}:${state.trialEndsAt}:${trialDays}` });
    }
    if (state.trialEndsAt && new Date(state.trialEndsAt).getTime() <= now.getTime()) await recordLifecycleEvent(deps, { userId: professional.id, eventName: "trial_expired", source: "backend", metadata: {}, idempotencyKey: `trial_expired:${professional.id}:${state.trialEndsAt}` });
    return result;
  });
  assertLifecycleSchedulerHealthy(batchResult, users.length);
  return { ...batchResult, dryRun: runtime.dry_run || !runtime.send_enabled, users: users.length };
}

