import { createHmac, timingSafeEqual } from "node:crypto";
import type {
  WhatsAppConfig,
  WhatsAppDeliveryRepository,
  WhatsAppMetaError,
  WhatsAppSendResult,
  WhatsAppTemplateSendInput,
  WhatsAppTextSendInput
} from "./whatsappTypes.js";

const DEFAULT_GRAPH_API_VERSION = "v25.0";

type WhatsAppLogger = Pick<Console, "info" | "warn" | "error">;

type WhatsAppClientDependencies = {
  config: WhatsAppConfig;
  repository: WhatsAppDeliveryRepository;
  fetchImpl?: typeof fetch;
  logger?: WhatsAppLogger;
};

export class WhatsAppValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "WhatsAppValidationError";
  }
}

export function getWhatsAppConfigFromEnv(
  env: NodeJS.ProcessEnv = process.env
): WhatsAppConfig {
  const graphApiVersion = String(env.WHATSAPP_GRAPH_API_VERSION || DEFAULT_GRAPH_API_VERSION).trim();
  return {
    sendEnabled: String(env.WHATSAPP_SEND_ENABLED || "").trim().toLowerCase() === "true",
    accessToken: String(env.WHATSAPP_ACCESS_TOKEN || "").trim(),
    phoneNumberId: String(env.WHATSAPP_PHONE_NUMBER_ID || "").trim(),
    graphApiVersion,
    appSecret: String(env.WHATSAPP_APP_SECRET || "").trim(),
    webhookVerifyToken: String(env.WHATSAPP_WEBHOOK_VERIFY_TOKEN || "").trim(),
    n8nEventsToken: String(env.WHATSAPP_N8N_EVENTS_TOKEN || "").trim(),
    optOutWebhookToken: String(env.WHATSAPP_OPT_OUT_WEBHOOK_TOKEN || "").trim(),
    userLookupToken: String(env.WHATSAPP_USER_LOOKUP_TOKEN || "").trim(),
    allowUnsignedWebhooks:
      env.NODE_ENV !== "production" &&
      String(env.WHATSAPP_ALLOW_UNSIGNED_WEBHOOKS || "false").toLowerCase() === "true"
  };
}

export function normalizeWhatsAppPhone(value: string): string {
  const normalized = String(value || "").replace(/\D/g, "");
  if (!normalized) {
    throw new WhatsAppValidationError("Número de telefone do WhatsApp é obrigatório.");
  }
  if (normalized.length < 8 || normalized.length > 15) {
    throw new WhatsAppValidationError("Número de telefone do WhatsApp deve conter DDI e entre 8 e 15 dígitos.");
  }
  return normalized;
}

export function maskWhatsAppPhone(value: string): string {
  const phone = String(value || "");
  if (phone.length <= 6) return "*".repeat(phone.length);
  return `${phone.slice(0, 4)}${"*".repeat(Math.max(5, phone.length - 8))}${phone.slice(-4)}`;
}

export function buildWhatsAppMessagesUrl(config: Pick<WhatsAppConfig, "graphApiVersion" | "phoneNumberId">): string {
  const version = String(config.graphApiVersion || DEFAULT_GRAPH_API_VERSION).trim();
  if (!/^v\d+\.\d+$/.test(version)) {
    throw new WhatsAppValidationError("WHATSAPP_GRAPH_API_VERSION deve seguir o formato vNN.N.");
  }
  if (!String(config.phoneNumberId || "").trim()) {
    throw new WhatsAppValidationError("WHATSAPP_PHONE_NUMBER_ID não configurada no servidor.");
  }
  return `https://graph.facebook.com/${version}/${encodeURIComponent(config.phoneNumberId.trim())}/messages`;
}

export function parseWhatsAppMetaError(payload: unknown): WhatsAppMetaError {
  const error = payload && typeof payload === "object" && "error" in payload
    ? (payload as { error?: Record<string, unknown> }).error || {}
    : {};
  return {
    code: error.code == null ? null : String(error.code),
    subcode: error.error_subcode == null ? null : String(error.error_subcode),
    type: error.type == null ? null : String(error.type),
    message: error.message == null ? null : String(error.message),
    userTitle: error.error_user_title == null ? null : String(error.error_user_title),
    userMessage: error.error_user_msg == null ? null : String(error.error_user_msg),
    fbtraceId: error.fbtrace_id == null ? null : String(error.fbtrace_id)
  };
}

export function extractWhatsAppWamid(payload: unknown): string | null {
  if (!payload || typeof payload !== "object") return null;
  const messages = (payload as { messages?: unknown }).messages;
  if (!Array.isArray(messages) || !messages[0] || typeof messages[0] !== "object") return null;
  const id = (messages[0] as { id?: unknown }).id;
  return typeof id === "string" && id.trim() ? id.trim() : null;
}

function sanitizedSuccessPayload(payload: unknown): Record<string, unknown> {
  return {
    messaging_product:
      payload && typeof payload === "object" && "messaging_product" in payload
        ? String((payload as { messaging_product?: unknown }).messaging_product || "")
        : "whatsapp",
    messages: extractWhatsAppWamid(payload) ? [{ id: extractWhatsAppWamid(payload) }] : []
  };
}

function sanitizedErrorPayload(error: WhatsAppMetaError): Record<string, unknown> {
  return {
    error: {
      code: error.code,
      error_subcode: error.subcode,
      type: error.type,
      message: error.message,
      error_user_title: error.userTitle,
      error_user_msg: error.userMessage,
      fbtrace_id: error.fbtraceId
    }
  };
}

function getConfigurationError(config: WhatsAppConfig): string | null {
  if (!config.sendEnabled) return "Envio bloqueado por WHATSAPP_SEND_ENABLED=false.";
  const missing: string[] = [];
  if (!config.accessToken) missing.push("WHATSAPP_ACCESS_TOKEN");
  if (!config.phoneNumberId) missing.push("WHATSAPP_PHONE_NUMBER_ID");
  return missing.length ? `Configuração obrigatória ausente: ${missing.join(", ")}.` : null;
}

function combinedErrorCode(error: WhatsAppMetaError): string | null {
  if (!error.code) return null;
  return error.subcode ? `${error.code}:${error.subcode}` : error.code;
}

function sanitizeProviderText(
  value: string | null,
  config: WhatsAppConfig,
  additionalSensitiveValues: string[] = []
): string | null {
  if (!value) return null;
  let sanitized = value;
  for (const secret of [
    config.accessToken,
    config.appSecret,
    config.webhookVerifyToken,
    config.n8nEventsToken,
    ...additionalSensitiveValues
  ]) {
    if (secret) sanitized = sanitized.split(secret).join("[REDACTED]");
  }
  return sanitized.slice(0, 1000);
}

function sanitizeMetaError(
  error: WhatsAppMetaError,
  config: WhatsAppConfig,
  additionalSensitiveValues: string[] = []
): WhatsAppMetaError {
  return {
    ...error,
    type: sanitizeProviderText(error.type, config, additionalSensitiveValues),
    message: sanitizeProviderText(error.message, config, additionalSensitiveValues),
    userTitle: sanitizeProviderText(error.userTitle, config, additionalSensitiveValues),
    userMessage: sanitizeProviderText(error.userMessage, config, additionalSensitiveValues),
    fbtraceId: sanitizeProviderText(error.fbtraceId, config, additionalSensitiveValues)
  };
}

export function verifyWhatsAppWebhookSignature(input: {
  rawBody: Buffer;
  signature: string;
  appSecret: string;
  allowUnsigned: boolean;
}): boolean {
  if (!input.appSecret) return input.allowUnsigned;
  if (!input.signature.startsWith("sha256=")) return false;

  const receivedHex = input.signature.slice("sha256=".length);
  if (!/^[a-fA-F0-9]{64}$/.test(receivedHex)) return false;
  const expected = createHmac("sha256", input.appSecret).update(input.rawBody).digest();
  const received = Buffer.from(receivedHex, "hex");
  return received.length === expected.length && timingSafeEqual(received, expected);
}

export function createWhatsAppClient(deps: WhatsAppClientDependencies) {
  const fetchImpl = deps.fetchImpl || fetch;
  const logger = deps.logger || console;

  async function sendPrepared(input: {
    userId?: string | null;
    lifecycleDispatchId?: string | null;
    recipientPhone: string;
    messageType: "text" | "template";
    templateName: string | null;
    requestBody: Record<string, unknown>;
    storedRequestPayload: Record<string, unknown>;
    sensitiveValues?: string[];
  }): Promise<WhatsAppSendResult> {
    const configurationError = getConfigurationError(deps.config);
    if (configurationError) {
      logger.error(`[WhatsApp] ${configurationError}`);
      return {
        success: false,
        deliveryId: null,
        wamid: null,
        status: "not_configured",
        httpStatus: null,
        errorCode: "configuration_error",
        errorTitle: "WhatsApp não configurado",
        errorMessage: configurationError
      };
    }

    const recipientPhone = normalizeWhatsAppPhone(input.recipientPhone);
    const maskedPhone = maskWhatsAppPhone(recipientPhone);
    const pending = await deps.repository.createPending({
      userId: input.userId || null,
      lifecycleDispatchId: input.lifecycleDispatchId || null,
      recipientPhone,
      phoneNumberId: deps.config.phoneNumberId,
      messageType: input.messageType,
      templateName: input.templateName,
      requestPayload: input.storedRequestPayload
    });

    let response: Response;
    let payload: unknown;
    try {
      response = await fetchImpl(buildWhatsAppMessagesUrl(deps.config), {
        method: "POST",
        headers: {
          Authorization: `Bearer ${deps.config.accessToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ ...input.requestBody, to: recipientPhone })
      });
      payload = await response.json().catch(() => ({}));
    } catch (error) {
      const errorMessage = sanitizeProviderText(
        error instanceof Error ? error.message : "Falha de conexão com a WhatsApp Graph API.",
        deps.config,
        [recipientPhone, ...(input.sensitiveValues || [])]
      ) || "Falha de conexão com a WhatsApp Graph API.";
      await deps.repository.markFailed(pending.id, {
        responsePayload: null,
        errorCode: "network_error",
        errorTitle: "Falha de conexão",
        errorMessage
      });
      logger.error(`[WhatsApp] deliveryId=${pending.id} phone=${maskedPhone} type=${input.messageType} status=failed http=none code=network_error`);
      return {
        success: false,
        deliveryId: pending.id,
        wamid: null,
        status: "failed",
        httpStatus: null,
        errorCode: "network_error",
        errorTitle: "Falha de conexão",
        errorMessage
      };
    }

    if (!response.ok) {
      const metaError = sanitizeMetaError(parseWhatsAppMetaError(payload), deps.config, [recipientPhone, ...(input.sensitiveValues || [])]);
      const errorCode = combinedErrorCode(metaError);
      const errorTitle = metaError.userTitle || metaError.type || "Erro da WhatsApp Graph API";
      const errorMessage = metaError.userMessage || metaError.message || "A Meta rejeitou o envio.";
      await deps.repository.markFailed(pending.id, {
        responsePayload: sanitizedErrorPayload(metaError),
        errorCode,
        errorTitle,
        errorMessage
      });
      logger.warn(`[WhatsApp] deliveryId=${pending.id} phone=${maskedPhone} type=${input.messageType} status=failed http=${response.status} code=${errorCode || "unknown"}`);
      return {
        success: false,
        deliveryId: pending.id,
        wamid: null,
        status: "failed",
        httpStatus: response.status,
        errorCode,
        errorTitle,
        errorMessage
      };
    }

    const wamid = extractWhatsAppWamid(payload);
    await deps.repository.markAccepted(pending.id, wamid, sanitizedSuccessPayload(payload));
    logger.info(`[WhatsApp] deliveryId=${pending.id} wamid=${wamid || "missing"} phone=${maskedPhone} type=${input.messageType} status=accepted http=${response.status}`);
    return {
      success: true,
      deliveryId: pending.id,
      wamid,
      status: "accepted",
      httpStatus: response.status,
      errorCode: null,
      errorTitle: null,
      errorMessage: null
    };
  }

  return {
    async sendText(input: WhatsAppTextSendInput): Promise<WhatsAppSendResult> {
      const requestBody = {
        messaging_product: "whatsapp",
        recipient_type: "individual",
        type: "text",
        text: {
          preview_url: input.previewUrl !== false,
          body: input.text
        }
      };
      return sendPrepared({
        ...input,
        messageType: "text",
        templateName: null,
        requestBody,
        storedRequestPayload: {
          messaging_product: "whatsapp",
          recipient_type: "individual",
          type: "text",
          text: {
            preview_url: requestBody.text.preview_url,
            character_count: input.text.length
          }
        },
        sensitiveValues: [input.text]
      });
    },

    async sendTemplate(input: WhatsAppTemplateSendInput): Promise<WhatsAppSendResult> {
      const templateName = String(input.templateName || "").trim();
      const languageCode = String(input.languageCode || "").trim();
      if (!/^[a-z0-9_]+$/.test(templateName)) {
        throw new WhatsAppValidationError("Nome do template do WhatsApp inválido.");
      }
      if (!/^[a-z]{2}(?:_[A-Z]{2})?$/.test(languageCode)) {
        throw new WhatsAppValidationError("Código de idioma do template do WhatsApp inválido.");
      }
      const components = input.components || [];
      const parameterValues = components.flatMap((component) => component.parameters.map((parameter) => parameter.text));
      const requestBody = {
        messaging_product: "whatsapp",
        recipient_type: "individual",
        type: "template",
        template: {
          name: templateName,
          language: { code: languageCode },
          ...(components.length ? { components } : {})
        }
      };
      return sendPrepared({
        ...input,
        messageType: "template",
        templateName,
        requestBody,
        storedRequestPayload: {
          messaging_product: "whatsapp",
          recipient_type: "individual",
          type: "template",
          template: {
            name: templateName,
            language: { code: languageCode },
            components: components.map((component) => ({
              type: component.type,
              ...(component.type === "button"
                ? { sub_type: component.sub_type, index: component.index }
                : {}),
              parameter_count: component.parameters.length
            }))
          }
        },
        sensitiveValues: parameterValues
      });
    }
  };
}

export type WhatsAppClient = ReturnType<typeof createWhatsAppClient>;

server/whatsapp/whatsappN8nEvents.ts:
import { timingSafeEqual } from "node:crypto";
import type {
  NormalizedWhatsAppN8nEvent,
  WhatsAppN8nEventType,
  WhatsAppN8nEventsRepository,
  WhatsAppN8nMessageStatus
} from "./whatsappTypes.js";

const EVENT_TYPES = new Set<WhatsAppN8nEventType>([
  "message_status",
  "business_app_echo",
  "coexistence_sync"
]);
const MESSAGE_STATUSES = new Set<WhatsAppN8nMessageStatus>([
  "sent",
  "delivered",
  "read",
  "failed"
]);
const SENSITIVE_KEYS = new Set([
  "authorization",
  "access_token",
  "app_secret",
  "client_secret",
  "service_role",
  "supabase_service_role_key",
  "whatsapp_n8n_events_token",
  "token"
]);

type WhatsAppN8nLogger = Pick<Console, "info" | "warn" | "error">;

export class WhatsAppN8nEventValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "WhatsAppN8nEventValidationError";
  }
}

function requiredString(value: unknown, field: string, maxLength: number): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new WhatsAppN8nEventValidationError(`${field} é obrigatório.`);
  }
  const normalized = value.trim();
  if (normalized.length > maxLength) {
    throw new WhatsAppN8nEventValidationError(`${field} excede o tamanho permitido.`);
  }
  return normalized;
}

function optionalString(value: unknown, field: string, maxLength: number): string | null {
  if (value == null || value === "") return null;
  return requiredString(value, field, maxLength);
}

function sanitizeRawValue(value: unknown, depth = 0): unknown {
  if (depth > 8) return "[TRUNCATED]";
  if (typeof value === "string") return value.slice(0, 4000);
  if (typeof value === "number" || typeof value === "boolean" || value === null) return value;
  if (Array.isArray(value)) return value.slice(0, 100).map((item) => sanitizeRawValue(item, depth + 1));
  if (!value || typeof value !== "object") return String(value).slice(0, 4000);

  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .slice(0, 100)
      .filter(([key]) => !SENSITIVE_KEYS.has(key.toLowerCase()))
      .map(([key, item]) => [key, sanitizeRawValue(item, depth + 1)])
  );
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function pickErrorValue(value: unknown): string | null {
  if (value == null) return null;
  const normalized = String(value).trim();
  return normalized ? normalized.slice(0, 1000) : null;
}

function extractEventError(rawValue: unknown) {
  const raw = asRecord(rawValue);
  const error = asRecord(raw?.error) || asRecord(raw?.errors?.[0]) || raw;
  return {
    errorCode: pickErrorValue(error?.code || error?.error_code),
    errorTitle: pickErrorValue(error?.error_user_title || error?.title || error?.type),
    errorMessage: pickErrorValue(error?.error_user_msg || error?.message || error?.details)
  };
}

export function validateNormalizedWhatsAppN8nEvent(payload: unknown): NormalizedWhatsAppN8nEvent {
  const input = asRecord(payload);
  if (!input) throw new WhatsAppN8nEventValidationError("Payload JSON deve ser um objeto.");

  const eventType = requiredString(input.eventType, "eventType", 64) as WhatsAppN8nEventType;
  if (!EVENT_TYPES.has(eventType)) {
    throw new WhatsAppN8nEventValidationError("eventType não é suportado.");
  }

  const receivedAtRaw = requiredString(input.receivedAt, "receivedAt", 64);
  const receivedAtDate = new Date(receivedAtRaw);
  if (Number.isNaN(receivedAtDate.getTime())) {
    throw new WhatsAppN8nEventValidationError("receivedAt deve ser uma data ISO válida.");
  }

  const messageId = optionalString(input.messageId, "messageId", 512);
  const statusValue = optionalString(input.status, "status", 32);
  const status = statusValue as WhatsAppN8nMessageStatus | null;

  if (eventType === "message_status") {
    if (!messageId) throw new WhatsAppN8nEventValidationError("messageId é obrigatório para message_status.");
    if (!status || !MESSAGE_STATUSES.has(status)) {
      throw new WhatsAppN8nEventValidationError("status deve ser sent, delivered, read ou failed.");
    }
  }

  return {
    tenant: requiredString(input.tenant, "tenant", 128),
    eventType,
    eventKey: requiredString(input.eventKey, "eventKey", 255),
    messageId,
    status: eventType === "message_status" ? status : null,
    receivedAt: receivedAtDate.toISOString(),
    phoneNumberId: optionalString(input.phoneNumberId, "phoneNumberId", 255),
    senderPhone: optionalString(input.senderPhone, "senderPhone", 64),
    recipientPhone: optionalString(input.recipientPhone, "recipientPhone", 64),
    rawValue: sanitizeRawValue(input.rawValue)
  };
}

export function verifyWhatsAppN8nEventsAuthorization(
  authorization: string | undefined,
  expectedToken: string
): boolean {
  const match = /^Bearer\s+(.+)$/i.exec(String(authorization || ""));
  const receivedToken = match?.[1]?.trim() || "";
  const configuredToken = String(expectedToken || "").trim();
  if (!receivedToken || !configuredToken) return false;

  const received = Buffer.from(receivedToken);
  const expected = Buffer.from(configuredToken);
  return received.length === expected.length && timingSafeEqual(received, expected);
}

export function createWhatsAppN8nEventsService(deps: {
  repository: WhatsAppN8nEventsRepository;
  logger?: WhatsAppN8nLogger;
}) {
  const logger = deps.logger || console;

  return {
    async process(event: NormalizedWhatsAppN8nEvent) {
      const claim = await deps.repository.claimN8nEvent(event);
      if (!claim.shouldProcess) {
        return { processed: true, alreadyProcessed: true, result: "already_processed" };
      }

      try {
        if (event.eventType !== "message_status") {
          await deps.repository.completeN8nEvent({
            eventId: claim.eventId,
            processingStatus: "ignored",
            deliveryId: null,
            processingResult: { action: "recorded_without_processing", eventType: event.eventType }
          });
          logger.info(`[WhatsApp n8n] eventKey=${event.eventKey} eventType=${event.eventType} result=recorded_without_processing`);
          return { processed: true, alreadyProcessed: false, result: "recorded_without_processing" };
        }

        const delivery = await deps.repository.findDeliveryByWamid(event.messageId!);
        if (!delivery) {
          await deps.repository.completeN8nEvent({
            eventId: claim.eventId,
            processingStatus: "ignored",
            deliveryId: null,
            processingResult: { action: "delivery_not_found", messageId: event.messageId }
          });
          logger.warn(`[WhatsApp n8n] eventKey=${event.eventKey} eventType=message_status result=delivery_not_found`);
          return { processed: true, alreadyProcessed: false, result: "delivery_not_found" };
        }

        const error = event.status === "failed"
          ? extractEventError(event.rawValue)
          : { errorCode: null, errorTitle: null, errorMessage: null };
        await deps.repository.updateDeliveryFromN8nEvent(delivery, {
          status: event.status!,
          receivedAt: event.receivedAt,
          eventKey: event.eventKey,
          tenant: event.tenant,
          phoneNumberId: event.phoneNumberId,
          ...error
        });
        await deps.repository.completeN8nEvent({
          eventId: claim.eventId,
          processingStatus: "processed",
          deliveryId: delivery.id,
          processingResult: { action: "delivery_status_updated", status: event.status }
        });
        logger.info(`[WhatsApp n8n] eventKey=${event.eventKey} eventType=message_status status=${event.status} result=updated`);
        return { processed: true, alreadyProcessed: false, result: "delivery_status_updated" };
      } catch (error) {
        const message = error instanceof Error ? error.message.slice(0, 1000) : "Erro interno ao processar evento.";
        await deps.repository.failN8nEvent(claim.eventId, message).catch(() => {});
        throw error;
      }
    }
  };
}

